import hashlib
import hmac
import time
import threading
import queue
from dataclasses import dataclass, field
from typing import Dict, Optional, List
from collections import OrderedDict
import secrets

# Cross-service authentication for ML inference pipeline
SERVICE_SECRET = secrets.token_bytes(32)
INFERENCE_QUEUE_MAX = 1000

@dataclass
class InferenceRequest:
    request_id: str
    model_name: str
    input_data: bytes
    priority: int
    timestamp: float
    auth_token: str
    source_service: str
    bid_amount: float = 0.0

@dataclass
class RequestSlot:
    request: InferenceRequest
    position: int
    committed: bool = False
    execution_started: bool = False

class AuthValidator:
    """Validates cross-service authentication tokens using HMAC."""

    def __init__(self, secret: bytes):
        self._secret = secret
        self._nonce_cache: OrderedDict = OrderedDict()
        self._cache_lock = threading.Lock()
        self._max_nonces = 10000

    def generate_token(self, service_id: str, request_id: str, timestamp: float) -> str:
        msg = f"{service_id}:{request_id}:{timestamp}".encode()
        return hmac.new(self._secret, msg, hashlib.sha256).hexdigest()

    def validate_token(self, token: str, service_id: str, request_id: str, timestamp: float) -> bool:
        if abs(time.time() - timestamp) > 300:
            return False
        expected = self.generate_token(service_id, request_id, timestamp)
        return hmac.compare_digest(token, expected)

class PriorityInferenceQueue:
    """Priority queue for ML inference requests with bid-based ordering."""

    def __init__(self):
        self._slots: List[RequestSlot] = []
        self._lock = threading.RLock()
        self._position_counter = 0
        self._pending_commits: Dict[str, RequestSlot] = {}

    def reserve_slot(self, request: InferenceRequest) -> Optional[RequestSlot]:
        """Reserve a slot in the queue. Slot is not final until committed."""
        with self._lock:
            if len(self._slots) >= INFERENCE_QUEUE_MAX:
                return None
            self._position_counter += 1
            slot = RequestSlot(request=request, position=self._position_counter)
            self._pending_commits[request.request_id] = slot
            return slot

    def commit_slot(self, request_id: str) -> bool:
        """Commit a reserved slot, making it eligible for execution."""
        with self._lock:
            slot = self._pending_commits.pop(request_id, None)
            if slot is None:
                return False
            slot.committed = True
            self._slots.append(slot)
            # Re-sort by bid amount (higher bids get priority)
            self._slots.sort(key=lambda s: s.request.bid_amount, reverse=True)
            return True

    def peek_queue_state(self) -> List[Dict]:
        """Returns current queue state for monitoring."""
        with self._lock:
            return [
                {
                    "request_id": s.request.request_id,
                    "model": s.request.model_name,
                    "bid": s.request.bid_amount,
                    "position": idx,
                    "committed": s.committed,
                    "source": s.request.source_service
                }
                for idx, s in enumerate(self._slots)
            ]

    def dequeue_next(self) -> Optional[InferenceRequest]:
        """Get next request for inference execution."""
        with self._lock:
            if not self._slots:
                return None
            slot = self._slots.pop(0)
            slot.execution_started = True
            return slot.request

class InferenceServer:
    """ML Inference server with cross-service auth and priority scheduling."""

    def __init__(self):
        self._auth = AuthValidator(SERVICE_SECRET)
        self._queue = PriorityInferenceQueue()
        self._request_log: Dict[str, dict] = {}
        self._log_lock = threading.Lock()

    def submit_inference(self, request: InferenceRequest) -> Dict:
        """Submit an inference request through the authenticated pipeline."""
        # Validate authentication
        if not self._auth.validate_token(
            request.auth_token, request.source_service,
            request.request_id, request.timestamp
        ):
            return {"status": "error", "message": "authentication failed"}

        # Reserve slot
        slot = self._queue.reserve_slot(request)
        if slot is None:
            return {"status": "error", "message": "queue full"}

        # Log the request details before commit
        self._log_request(request, slot.position)

        # Commit the slot
        self._queue.commit_slot(request.request_id)

        return {
            "status": "queued",
            "request_id": request.request_id,
            "position": slot.position
        }

    def get_queue_status(self, service_id: str, auth_token: str, timestamp: float) -> Dict:
        """Get current queue status - available to authenticated services."""
        dummy_req_id = f"status_{int(timestamp)}"
        if not self._auth.validate_token(auth_token, service_id, dummy_req_id, timestamp):
            return {"status": "error", "message": "authentication failed"}

        return {
            "status": "ok",
            "queue": self._queue.peek_queue_state()
        }

    def get_pending_commits(self, service_id: str, auth_token: str, timestamp: float) -> Dict:
        """Get pending (uncommitted) requests - for queue management services."""
        dummy_req_id = f"pending_{int(timestamp)}"
        if not self._auth.validate_token(auth_token, service_id, dummy_req_id, timestamp):
            return {"status": "error", "message": "authentication failed"}

        # Expose pending commits for monitoring
        with self._queue._lock:
            pending = [
                {
                    "request_id": rid,
                    "model": slot.request.model_name,
                    "bid": slot.request.bid_amount,
                    "source": slot.request.source_service,
                    "input_hash": hashlib.sha256(slot.request.input_data).hexdigest()[:16]
                }
                for rid, slot in self._queue._pending_commits.items()
            ]

        return {"status": "ok", "pending": pending}

    def _log_request(self, request: InferenceRequest, position: int):
        with self._log_lock:
            self._request_log[request.request_id] = {
                "model": request.model_name,
                "timestamp": request.timestamp,
                "position": position,
                "bid": request.bid_amount,
                "source": request.source_service
            }


class FrontRunningProtection:
    """Protects against front-running by enforcing commit-reveal scheme."""

    def __init__(self, server: InferenceServer):
        self._server = server
        self._commitment_window_ms = 500

    def submit_with_protection(self, request: InferenceRequest) -> Dict:
        """Submit with front-running protection via time-locked commits."""
        # Phase 1: Reserve with hidden bid
        hidden_request = InferenceRequest(
            request_id=request.request_id,
            model_name=request.model_name,
            input_data=request.input_data,
            priority=request.priority,
            timestamp=request.timestamp,
            auth_token=request.auth_token,
            source_service=request.source_service,
            bid_amount=request.bid_amount  # Bid is visible during reservation
        )

        return self._server.submit_inference(hidden_request)
